size_t RegisterJPEGImage(void) {
  MagickInfo *magick_info;

  magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(MagickInfo));
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  (void) ConstantString(magick_info->version,"JPEG 9.1.0");
  (void) ConstantString(magick_info->description,"JPEG image format");
  magick_info->decoder = (AcquireImageHandler) JPEGDecodeImage;
  magick_info->encoder = (AcquireImageHandler) JPEGEncodeImage;
  magick_info->thread_support = MagickTrue;
  (void) ConstantString(magick_info->mime_type,"image/jpeg");

  /* Check JPEG library version for thread support */
#if defined(MAGICKCORE_JPEG_SUPPORT)
  {
    extern char* jpeg_version_id;
    if (strncmp(jpeg_version_id, "9", 1) != 0)
      magick_info->thread_support = MagickFalse;
  }
#endif

  RegisterMagickInfo("JPE", magick_info);
  RegisterMagickInfo("JPEG", magick_info);
  RegisterMagickInfo("JPG", magick_info);
  RegisterMagickInfo("JPS", magick_info);
  RegisterMagickInfo("PJPEG", magick_info);

  return sizeof(MagickInfo);
}

size_t RegisterJPEGImage(void) {
    MagickInfo
        *magick_info;

    MagickInfo
        *magick_info_entry;

    char
        version[MagickPathExtent];

    /* Initialize the version string and description for the JPEG format */
    (void) FormatLocaleString(version, MagickPathExtent, "JPEG %s", JPEG_VERSION);

    magick_info = AcquireMagickInfo("JPEG", "JPE", "JPEG image");
    magick_info->decoder = (DecodeImageHandler *) JPEGReadImage;
    magick_info->encoder = (EncodeImageHandler *) JPEGWriteImage;
    magick_info->thread_support = MagickFalse;
    magick_info->mime_type = ConstantString("image/jpeg");
    magick_info->description = ConstantString("JPEG (Joint Photographic Experts Group) image format");
    magick_info->module = ConstantString("JPEG");

    magick_info_entry = CloneMagickInfo(magick_info);
    magick_info_entry->name = ConstantString("JPEG");
    magick_info_entry->description = ConstantString("JPEG image");
    magick_info_entry = CloneMagickInfo(magick_info);
    magick_info_entry->name = ConstantString("JPG");
    magick_info_entry = CloneMagickInfo(magick_info);
    magick_info_entry->name = ConstantString("JPS");
    magick_info_entry = CloneMagickInfo(magick_info);
    magick_info_entry->name = ConstantString("PJPEG");

    if (JPEG_SUPPORT_THREADS)
        magick_info->thread_support = MagickTrue;

    (void) RegisterMagickInfo(magick_info);

    return sizeof(*magick_info);
}

size_t RegisterJPEGImage(void) {
  MagickInfo *magick_info;

  magick_info = (MagickInfo *) AcquireMagickMemory(sizeof(*magick_info));
  if (magick_info == (MagickInfo *) NULL)
    return 0;

  magick_info->decoder = JPEGReadImage;
  magick_info->encoder = JPEGWriteImage;
  magick_info->thread_support = MagickTrue;
  magick_info->mime_type = ConstantString("image/jpeg");

  magick_info->description = ConstantString("JPEG image format");
  magick_info->version = ConstantString("JPEG library version 9");

#if defined(MAGICKCORE_JPEG_DELEGATE)
  {
    extern size_t JPEGThreadSupport;

    magick_info->thread_support = (JPEGThreadSupport != 0 ? MagickTrue : MagickFalse);
  }
#endif

  (void) RegisterMagickInfo("JPE", magick_info);
  (void) RegisterMagickInfo("JPEG", magick_info);
  (void) RegisterMagickInfo("JPG", magick_info);
  (void) RegisterMagickInfo("JPS", magick_info);
  (void) RegisterMagickInfo("PJPEG", magick_info);

  return sizeof(*magick_info);
}

